import { createSlice, } from '@reduxjs/toolkit';
const initialState = {
    realized_pnl: 0,
    date_range: null,
};
export const tradeHistorySlice = createSlice({
    name: 'tradeHistory',
    initialState,
    reducers: {
        calculateRealizedPNL: (state, action) => {
            let realized_pnl = 0;
            action.payload.forEach(item => {
                realized_pnl = realized_pnl + item.trade_pnl_current;
            });
            state.realized_pnl = realized_pnl;
        },
        setDateRange: (state, action) => {
            state.date_range = action.payload;
        },
        resetTradeHistorySlice() {
            return initialState;
        },
    }
});
export const { actions: tradeHistoryActions } = tradeHistorySlice;
export const { reducer: tradeHistoryReducer } = tradeHistorySlice;
